import React, {useState, useEffect} from 'react';
import Stack from '@mui/material/Stack';
import { Box } from '@mui/material';
import Dialogo from '../../../componentes/herramientas/dialogo';
import DialogoR from '../../../componentes/herramientas/dialogo';
import IconButton from '@mui/material/IconButton';
import Icon from '@mui/material/Icon';
import Alert from '@mui/material/Alert';
import CircularProgress from '@mui/material/CircularProgress';
import TablaMultiple from '../../../componentes/herramientas/tabla/tabla_multiple';
import Tabla from '../../../componentes/herramientas/tabla';
import Cuerpo from '../../../componentes/herramientas/cuerpo'
import {Condicion_Estudiante, Condicion_Representante} from '../funciones';
import { Abrir_Recibo } from '../funciones';
import { Ver_Valores, conexiones, Form_todos, Titulos_todos, AExcell } from '../../../constantes';
import Reporte from '../../../componentes/reporte';
import RetencionPDF from '../../reportes/retencionpdf';

import Cargando from '../../../componentes/esperar/cargar';

import excel from '../../../imagenes/excel.png';
import DescargaExcel from '../../../componentes/descargaExcel';
import { removeAllListeners } from 'process';
import moment from 'moment';

function Retencion (props) {
    
    const [state, setState]= useState({esperar:true, Dialogo:{open:false}, Dialogo1:{open:false}});
    let DialogoA ={open:false};
    const cambiarState = (nuevostate)=>{
        setState({...state, ...nuevostate, cambio:true})
    }
    
    const Condiciones = async(campo, datos) =>{
        let {valores}= datos
        
        Object.keys(valores).map(val=>{
            if(val.indexOf('titulo')!==-1){
                delete valores[val];
            }

        })
        
        return valores
        // switch (campo) {
           
        //     default:
        //         return valores;
        // }
    
    }

    const Abrir_retencion = async(valores, descargar=false)=>{
            
        console.log(valores)
        setState({
            ...state,
            Dialogo:{            
                ...state.Dialogo, 
                open: !state.Dialogo.open,
                // tam:'xl',
                Titulo: `Retención: ${valores.numero} `,
                Cuerpo: <Reporte  
                                datos={valores} 
                                descargar={descargar} nombredoc={valores.numero} 
                                reporte={RetencionPDF} sizePagina= {{width:612, height:396}} 
                                cerrar={()=>setState({...state, Dialogo:{...state,Dialogo,open:false}})}
                        />,
                Cerrar: ()=>setState({...state, Dialogo:{...state,Dialogo,open:false}}),
            }
        })

    }
    
    const Titulo = (dato)=>{
        const texto = dato._id ? `Retención ${dato.numero}`: `Nueva Retención`
        return <Stack
                    direction={ 'row' }
                    spacing={1}
                    justifyContent="center" alignItems="center"
                >
                    {texto}
                    {dato._id
                        ?   <div>
                                <IconButton size="large" color="inherit" title={'Mostrar Retención'} onClick={()=>Abrir_retencion(dato)}>
                                    <Icon >text_snippet</Icon>
                                </IconButton>
                                <IconButton size="large" color="inherit" title={'Descargar Retención'} onClick={()=>Abrir_retencion(dato, true)}>
                                    <Icon >download</Icon>
                                </IconButton>
                            </div>
                        :null
                    }
                </Stack>

    }
    const Inicio = async() =>{
        const titulos = await Titulos_todos(`Titulos_Retencion`, Config)
        cambiarState({esperar:false, titulos})
    }
    
    
    let buscado;
    const Actualizar_data = (valores)=>{
        console.log(valores.length)
        if (valores.length!==0)
            buscado=valores;
        // cambiarState({buscado:valores})
    }
    
    
    useEffect(()=>{
        Inicio()
        return ()=>{
            removeAllListeners(Inicio)
        }
    }, [props])

    const {Config}= props;
    const color =  props.Config.Estilos.Input_icono_t ? props.Config.Estilos.Input_icono_t : {};

    return state.esperar ? <Cargando open={state.esperar} Config={Config}/> : (
        <Box>
            <TablaMultiple
                Config={Config ? Config : Ver_Valores().config}
                multiples_valores={true}
                Agregar_mas={false}
                Condiciones={Condiciones}
                Columnas={2} 
                Form_origen = {Form_todos(`Form_Retencion`, Config)}
                Titulo_tabla={'Retenciones'}
                Table = {'uecla_Retencion'}
                Eliminar_props={(dato)=>{
                    return `Desea eliminar retención ${dato.codigo}`
                }}
                Titulo_dialogo ={Titulo}
                Titulos_tabla = {state.titulos}
                cargaporparte = {true}
                sinpaginacion = {false}
                cargacompleta={Actualizar_data}
                Tam_dialogo={'xl'}
                AgregarAccion={
                    <div>
                       
                    </div>
                }
                
            />
            <Dialogo {...state.Dialogo} config={Config}/>
            <DialogoR {...state.Dialogo1} config={Config}/>
        </Box>
    )
}

export default Retencion;